class Solution:
    def removeInvalidParentheses(self, s: str) -> list[str]:
        def valid(t):
            bal = 0
            for ch in t:
                if ch == '(':
                    bal += 1
                elif ch == ')':
                    bal -= 1
                    if bal < 0:
                        return False
            return bal == 0
        best_len = -1
        ans = set()
        n = len(s)
        for mask in range(1 << n):
            if mask.bit_count() < best_len:
                continue
            t = ''.join(s[i] for i in range(n) if mask & (1 << i))
            if valid(t):
                if len(t) > best_len:
                    best_len = len(t)
                    ans.clear()
                ans.add(t)
        return sorted(ans)

