class Solution:
    def removeInvalidParentheses(self, s: str) -> list[str]:
        def valid(t):
            bal = 0
            for ch in t:
                if ch == '(':
                    bal += 1
                elif ch == ')':
                    bal -= 1
                    if bal < 0:
                        return False
            return bal == 0
        level = {s}
        while True:
            good = [t for t in level if valid(t)]
            if good:
                return sorted(good)
            nxt = set()
            for t in level:
                for i, ch in enumerate(t):
                    if ch in '()':
                        nxt.add(t[:i] + t[i + 1:])
            level = nxt

