class Solution:
    def removeInvalidParentheses(self, s: str) -> list[str]:
        lrem = rrem = 0
        for ch in s:
            if ch == '(':
                lrem += 1
            elif ch == ')':
                if lrem:
                    lrem -= 1
                else:
                    rrem += 1
        ans = set()
        def dfs(i, bal, lrem, rrem, path):
            if i == len(s):
                if bal == 0 and lrem == 0 and rrem == 0:
                    ans.add(''.join(path))
                return
            ch = s[i]
            if ch == '(':
                if lrem:
                    dfs(i + 1, bal, lrem - 1, rrem, path)
                path.append(ch)
                dfs(i + 1, bal + 1, lrem, rrem, path)
                path.pop()
            elif ch == ')':
                if rrem:
                    dfs(i + 1, bal, lrem, rrem - 1, path)
                if bal:
                    path.append(ch)
                    dfs(i + 1, bal - 1, lrem, rrem, path)
                    path.pop()
            else:
                path.append(ch)
                dfs(i + 1, bal, lrem, rrem, path)
                path.pop()
        dfs(0, 0, lrem, rrem, [])
        return sorted(ans)

